input.content:
/* ==========================================================================
   RevvLot — Retro 90s Web Used Car Marketplace
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=IBM+Plex+Mono:wght@400;500;700&family=Archivo:wght@700;900&display=swap');

:root {
  --lot-black: #0A0A0A;
  --revv-cyan: #00F5FF;
  --turbo-purple: #CC00FF;
  --nitro-lime: #AAFF00;
  --screen-fog: #1C1C2E;
  --pixel-magenta: #FF2D78;
  --crt-white: #E8F0F2;
  --gridline-gray: #2E2E44;
  --font-heading: 'Press Start 2P', monospace;
  --font-body: 'IBM Plex Mono', monospace;
  --font-accent: 'Archivo', sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--lot-black);
  color: var(--crt-white);
  line-height: 1.75;
  font-size: 15px;
  overflow-x: hidden;
  background-image:
    repeating-linear-gradient(0deg, rgba(46,46,68,0.05) 0 1px, transparent 1px 4px),
    repeating-linear-gradient(90deg, rgba(46,46,68,0.05) 0 1px, transparent 1px 4px);
}

a { color: var(--revv-cyan); text-decoration: none; }
a:hover { text-decoration: underline; }

img, svg { max-width: 100%; display: block; }

/* ============= NAV ============= */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--lot-black);
  border-bottom: 2px solid var(--turbo-purple);
}

.nav__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 32px;
  gap: 24px;
}

.nav__brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-heading);
  font-size: 16px;
  color: var(--revv-cyan);
  text-shadow: 0 0 8px rgba(0,245,255,0.45);
}

.nav__brand-mark {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
}

.nav__links {
  display: flex;
  gap: 4px;
  list-style: none;
}

.nav__links a {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
  padding: 8px 12px;
  border: 2px solid transparent;
  display: inline-block;
}

.nav__links a:hover,
.nav__links a.is-active {
  color: var(--revv-cyan);
  border-color: var(--revv-cyan);
  text-decoration: none;
}

.nav__cta {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--revv-cyan);
  color: var(--lot-black);
  padding: 10px 18px;
  border: 2px solid var(--revv-cyan);
  box-shadow: 4px 4px 0 var(--turbo-purple);
}

.nav__cta:hover { text-decoration: none; background: var(--nitro-lime); border-color: var(--nitro-lime); }

/* ============= BUTTONS ============= */
.btn {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 14px 28px;
  border: 3px solid var(--revv-cyan);
  background: var(--revv-cyan);
  color: var(--lot-black);
  display: inline-block;
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--lot-black);
  transition: transform .15s ease, box-shadow .15s ease;
}

.btn:hover {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--lot-black);
  text-decoration: none;
  background: var(--nitro-lime);
  border-color: var(--nitro-lime);
}

.btn--secondary {
  background: transparent;
  color: var(--crt-white);
  border-color: var(--crt-white);
  box-shadow: 4px 4px 0 var(--gridline-gray);
}

.btn--secondary:hover {
  background: transparent;
  color: var(--revv-cyan);
  border-color: var(--revv-cyan);
}

.btn--purple {
  background: var(--turbo-purple);
  color: var(--crt-white);
  border-color: var(--turbo-purple);
}

.btn--purple:hover {
  background: var(--pixel-magenta);
  border-color: var(--pixel-magenta);
  color: var(--crt-white);
}

.btn--lime {
  background: var(--nitro-lime);
  border-color: var(--lot-black);
  color: var(--lot-black);
}

.btn--block {
  background: var(--lot-black);
  border-color: var(--lot-black);
  color: var(--crt-white);
}

.btn--block:hover {
  background: var(--revv-cyan);
  border-color: var(--lot-black);
  color: var(--lot-black);
}

/* ============= EYEBROW ============= */
.eyebrow {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
}

.eyebrow::before {
  content: "";
  width: 32px;
  height: 2px;
  background: currentColor;
  display: inline-block;
}

.eyebrow--lime { color: var(--nitro-lime); }
.eyebrow--purple { color: var(--turbo-purple); }
.eyebrow--magenta { color: var(--pixel-magenta); }
.eyebrow--black { color: var(--lot-black); }

/* ============= TYPOGRAPHY ============= */
h1, h2, h3, h4 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  line-height: 1.3;
  letter-spacing: 0;
  color: var(--crt-white);
}

h1 { font-size: 36px; }
h2 { font-size: 24px; }
h3 { font-size: 14px; }

p { font-family: var(--font-body); }

.lead {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--crt-white);
  max-width: 560px;
  line-height: 1.75;
}

/* ============= LAYOUT ============= */
.section {
  padding: 80px 32px;
  position: relative;
  overflow: hidden;
}

.container {
  max-width: 1280px;
  margin: 0 auto;
  width: 100%;
}

.section--screen { background: var(--screen-fog); }
.section--purple { background: var(--turbo-purple); }
.section--magenta { background: var(--pixel-magenta); }

/* ============= STRUCTURAL DIVIDERS ============= */
.purple-rule {
  height: 8px;
  width: 100%;
  background:
    repeating-linear-gradient(90deg, var(--turbo-purple) 0 8px, var(--lot-black) 8px 10px);
}

.checker-strip {
  height: 16px;
  background:
    repeating-conic-gradient(var(--nitro-lime) 0 25%, var(--lot-black) 0 50%) 0 0 / 16px 16px;
}

.checker-strip--gray {
  background:
    repeating-conic-gradient(var(--gridline-gray) 0 25%, var(--lot-black) 0 50%) 0 0 / 16px 16px;
}

.checker-strip--magenta {
  background:
    repeating-conic-gradient(var(--pixel-magenta) 0 25%, #c2225f 0 50%) 0 0 / 16px 16px;
}

/* ============= HOME — HERO ============= */
.hero {
  background: var(--lot-black);
  padding: 80px 32px 60px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(45deg, rgba(46,46,68,0.4) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(46,46,68,0.4) 25%, transparent 25%);
  background-size: 8px 8px;
  opacity: 0.07;
  pointer-events: none;
}

.hero__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 24px;
  position: relative;
  align-items: center;
}

.hero__title {
  font-size: 64px;
  line-height: 1.1;
  margin-top: 16px;
  margin-bottom: 24px;
  position: relative;
  z-index: 3;
}

.hero__title-line-1 {
  color: var(--revv-cyan);
  display: block;
  white-space: nowrap;
  margin-right: -160px;
  text-shadow:
    4px 4px 0 var(--lot-black),
    0 0 18px rgba(0,245,255,0.35);
}

.hero__title-line-2 {
  color: var(--crt-white);
  display: block;
}

.hero__lead {
  margin-bottom: 32px;
}

.hero__ctas { display: flex; gap: 16px; flex-wrap: wrap; }

.hero__visual {
  position: relative;
  z-index: 1;
}

.browser-frame {
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 24px rgba(0,245,255,0.25);
}

.browser-frame__bar {
  background: var(--gridline-gray);
  border-bottom: 2px solid var(--revv-cyan);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
}

.browser-frame__dot {
  width: 12px;
  height: 12px;
  background: var(--pixel-magenta);
}
.browser-frame__dot:nth-child(2) { background: var(--nitro-lime); }
.browser-frame__dot:nth-child(3) { background: var(--revv-cyan); }

.browser-frame__url {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--crt-white);
  background: var(--lot-black);
  padding: 4px 12px;
  margin-left: 12px;
  flex: 1;
  border: 1px solid var(--gridline-gray);
}

.browser-frame__body { padding: 0; }

/* ============= STATS SECTION ============= */
.stats {
  background: var(--screen-fog);
  position: relative;
  padding: 56px 32px;
}

.stats::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-conic-gradient(var(--gridline-gray) 0 25%, transparent 0 50%) 0 0 / 16px 16px;
  opacity: 0.5;
  pointer-events: none;
}

.stats__inner { position: relative; }

.stats__head { margin-bottom: 32px; }

.stat-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 2px solid var(--revv-cyan);
}

.stat-card {
  padding: 28px 20px 20px 28px;
  border-right: 1px solid var(--gridline-gray);
  position: relative;
}

.stat-card:last-child { border-right: none; }

.stat-card__cat {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gridline-gray);
  margin-bottom: 12px;
}

.stat-card__num {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 48px;
  color: var(--nitro-lime);
  line-height: 1;
  text-shadow: 0 0 12px rgba(170,255,0,0.35);
}

.stat-card__desc {
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.6;
  margin-top: 12px;
}

/* ============= FEATURE GRID (HOME) ============= */
.feature-grid-section {
  background: var(--lot-black);
}

.feature-grid-layout {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 32px;
  align-items: start;
}

.feature-grid-text {
  border-right: 2px solid var(--turbo-purple);
  padding-right: 32px;
}

.feature-grid-text h2 {
  font-size: 18px;
  line-height: 1.5;
  margin-bottom: 16px;
}

.feature-grid-text p { margin-bottom: 24px; max-width: none; }

.feature-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.feature-card {
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 28px;
  position: relative;
  transition: border-color .2s ease, box-shadow .2s ease;
}

.feature-card:hover {
  border-color: var(--revv-cyan);
  box-shadow: 0 0 18px rgba(0,245,255,0.2);
}

.feature-card::after {
  content: "";
  position: absolute;
  bottom: 8px;
  right: 8px;
  width: 4px;
  height: 4px;
  background: var(--turbo-purple);
}

.feature-card:nth-child(4) { transform: translateY(16px); }

.feature-card__icon {
  width: 40px;
  height: 40px;
  margin-bottom: 16px;
  color: var(--revv-cyan);
}

.feature-card h3 {
  font-size: 12px;
  margin-bottom: 12px;
  line-height: 1.5;
}

.feature-card p {
  font-size: 13px;
  line-height: 1.7;
}

/* ============= TIMELINE (HOME) ============= */
.timeline-section { background: var(--lot-black); }

.timeline-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 40px;
  position: relative;
}

.timeline-row::before {
  content: "";
  position: absolute;
  top: 24px;
  left: 24px;
  right: 24px;
  height: 0;
  border-top: 2px dashed var(--revv-cyan);
  z-index: 0;
}

.timeline-step { position: relative; }

.timeline-node {
  width: 48px;
  height: 48px;
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 20px;
  color: var(--nitro-lime);
  position: relative;
  z-index: 1;
  margin-bottom: 20px;
}

.timeline-step__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  margin-bottom: 8px;
}

.timeline-step__desc {
  font-size: 14px;
  color: var(--crt-white);
  line-height: 1.7;
}

.timeline-cta {
  text-align: center;
  margin-top: 48px;
}

/* ============= TESTIMONIALS ============= */
.testimonials {
  background: var(--turbo-purple);
  padding: 80px 32px;
}

.testimonials__head h2 { color: var(--lot-black); }

.testimonial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
  align-items: start;
}

.testimonial-card {
  background: var(--lot-black);
  border: 2px solid var(--crt-white);
  padding: 28px;
  position: relative;
}

.testimonial-card:nth-child(2) { transform: translateY(32px); }
.testimonial-card:nth-child(3) { transform: translateY(48px); }

.testimonial-card__quote {
  position: absolute;
  top: -28px;
  left: 16px;
  font-family: var(--font-body);
  font-size: 64px;
  color: var(--nitro-lime);
  line-height: 1;
  text-shadow: 0 0 14px rgba(170,255,0,0.5);
}

.testimonial-card__text {
  font-size: 14px;
  color: var(--crt-white);
  line-height: 1.75;
  margin-top: 8px;
}

.testimonial-card__attr {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  margin-top: 16px;
}

.testimonial-card__sticker {
  position: absolute;
  bottom: -14px;
  right: -10px;
  background: var(--pixel-magenta);
  color: var(--crt-white);
  border: 3px solid var(--pixel-magenta);
  padding: 6px 10px;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.08em;
  transform: rotate(4deg);
  box-shadow: 3px 3px 0 var(--lot-black);
}

/* ============= FOOTER ============= */
.footer {
  background: var(--lot-black);
  border-top: 4px solid var(--revv-cyan);
  padding: 48px 32px 32px;
  color: var(--crt-white);
}

.footer__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 32px;
}

.footer h4 {
  font-size: 11px;
  color: var(--nitro-lime);
  margin-bottom: 16px;
}

.footer ul { list-style: none; }
.footer li { margin-bottom: 8px; font-size: 13px; }
.footer a { color: var(--crt-white); }
.footer a:hover { color: var(--revv-cyan); }

.footer__brand {
  font-family: var(--font-heading);
  color: var(--revv-cyan);
  font-size: 18px;
  margin-bottom: 16px;
}

.footer__copy {
  max-width: 1280px;
  margin: 32px auto 0;
  padding-top: 16px;
  border-top: 1px solid var(--gridline-gray);
  font-size: 12px;
  color: var(--gridline-gray);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

/* ============= PRODUCT PAGE ============= */
.page-header-masthead {
  position: relative;
  background: var(--lot-black);
  padding: 96px 32px 56px;
  overflow: hidden;
  min-height: 320px;
}

.page-header-masthead::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("assets/car-pattern.svg");
  background-size: 80px 80px;
  opacity: 0.18;
  pointer-events: none;
}

.page-header-masthead h1 { font-size: 32px; line-height: 1.4; margin-bottom: 20px; }
.page-header-masthead .lead { color: rgba(232,240,242,0.8); }
.page-header-masthead__inner { position: relative; max-width: 1280px; margin: 0 auto; }

.filter-section {
  background: var(--screen-fog);
  padding: 48px 32px;
}

.filter-section__head { max-width: 1280px; margin: 0 auto 24px; }
.filter-section__head h2 { color: var(--revv-cyan); margin-bottom: 12px; }
.filter-section__head p { font-size: 15px; max-width: 600px; }

.filter-window {
  max-width: 1280px;
  margin: 0 auto;
  background: var(--lot-black);
  border: 2px solid var(--revv-cyan);
}

.filter-window__bar {
  background: var(--gridline-gray);
  height: 32px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  border-bottom: 2px solid var(--revv-cyan);
  position: relative;
}

.filter-window__dot {
  width: 10px;
  height: 10px;
  background: var(--pixel-magenta);
}
.filter-window__dot:nth-child(2) { background: var(--nitro-lime); }
.filter-window__dot:nth-child(3) { background: var(--revv-cyan); }

.filter-window__label {
  font-family: var(--font-body);
  font-size: 11px;
  color: var(--crt-white);
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  letter-spacing: 0.05em;
}

.filter-window__body { padding: 28px; }

.filter-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 24px;
}

.filter-field label {
  display: block;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
  margin-bottom: 8px;
}

.filter-field input[type="text"] {
  width: 100%;
  background: var(--lot-black);
  border: 2px solid var(--revv-cyan);
  color: var(--crt-white);
  font-family: var(--font-body);
  font-size: 14px;
  padding: 10px 12px;
}

.filter-field input::placeholder { color: var(--gridline-gray); }

.range-bar {
  position: relative;
  height: 12px;
  background: var(--gridline-gray);
  margin: 14px 0 8px;
}

.range-bar__fill {
  position: absolute;
  top: 0;
  left: 25%;
  right: 25%;
  height: 100%;
  background: var(--revv-cyan);
}

.range-bar--purple .range-bar__fill { background: var(--turbo-purple); }

.range-bar__handle {
  position: absolute;
  top: -2px;
  width: 12px;
  height: 16px;
  background: var(--nitro-lime);
}

.range-bar__handle--left { left: calc(25% - 6px); }
.range-bar__handle--right { right: calc(25% - 6px); }

.range-labels {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--crt-white);
}

.chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  background: var(--gridline-gray);
  border: 2px solid var(--gridline-gray);
  color: var(--crt-white);
  padding: 6px 10px;
}

.chip.is-active {
  border-color: var(--revv-cyan);
  color: var(--revv-cyan);
  background: rgba(0,245,255,0.06);
}

.filter-search-btn {
  width: 100%;
  height: 48px;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--revv-cyan);
  color: var(--lot-black);
  border: 2px solid var(--lot-black);
  cursor: pointer;
}

.filter-search-btn:hover { background: var(--nitro-lime); }

/* Item Grid */
.item-grid-section {
  background: var(--lot-black);
  padding: 72px 0 64px;
  overflow: hidden;
}

.item-grid-head {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 32px;
}

.item-grid-headline {
  font-size: 64px;
  white-space: nowrap;
  color: var(--revv-cyan);
  margin: 16px 0 8px -10px;
  text-shadow: 4px 4px 0 var(--lot-black), 0 0 18px rgba(0,245,255,0.35);
  width: max-content;
}

.item-grid-head .purple-line {
  height: 4px;
  background: var(--turbo-purple);
  width: 100vw;
  margin-left: -32px;
  margin-bottom: 0;
}

.item-grid-head .lead {
  color: rgba(232,240,242,0.7);
  margin-top: 20px;
  font-size: 14px;
}

.item-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px 16px;
  max-width: 1280px;
  margin: 40px auto 0;
  padding: 0 32px;
}

.item-card {
  background: var(--screen-fog);
  border: 2px solid var(--revv-cyan);
  position: relative;
  padding: 28px 20px 16px;
  display: flex;
  flex-direction: column;
}

.item-card__badge {
  position: absolute;
  top: -10px;
  left: -10px;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 9px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  background: var(--nitro-lime);
  color: var(--lot-black);
  padding: 6px 10px;
  border: 2px solid var(--lot-black);
  box-shadow: 3px 3px 0 var(--lot-black);
  z-index: 2;
}

.item-card__badge--cyan { background: var(--revv-cyan); }
.item-card__badge--magenta { background: var(--pixel-magenta); color: var(--crt-white); }
.item-card__badge--purple { background: var(--turbo-purple); color: var(--crt-white); }
.item-card__badge--gray { background: var(--gridline-gray); color: var(--crt-white); }

.item-card__title {
  font-family: var(--font-heading);
  font-size: 13px;
  color: var(--crt-white);
  margin-bottom: 6px;
  line-height: 1.5;
}

.item-card__price {
  font-family: var(--font-heading);
  font-size: 13px;
  color: var(--nitro-lime);
  margin-bottom: 12px;
}

.item-card__specs {
  font-family: var(--font-body);
  font-size: 12px;
  color: rgba(232,240,242,0.85);
  margin-bottom: 8px;
}

.item-card__status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-body);
  font-size: 11px;
  color: var(--crt-white);
  margin-bottom: 12px;
}

.item-card__status::before {
  content: "";
  width: 8px;
  height: 8px;
  background: var(--nitro-lime);
  border-radius: 50%;
  display: inline-block;
}

.item-card__loc {
  display: inline-block;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  background: var(--gridline-gray);
  color: var(--crt-white);
  padding: 4px 8px;
  margin-bottom: 12px;
  width: fit-content;
}

.item-card__divider {
  border-top: 1px solid var(--gridline-gray);
  margin: 8px 0 12px;
}

.item-card__cta-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: auto;
}

.item-card__cta-row a {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  text-align: center;
  padding: 10px 8px;
  border: 2px solid var(--revv-cyan);
  color: var(--revv-cyan);
}

.item-card__cta-row a:first-child { background: transparent; }
.item-card__cta-row a:last-child { background: var(--revv-cyan); color: var(--lot-black); }
.item-card__cta-row a:hover { text-decoration: none; background: var(--nitro-lime); border-color: var(--nitro-lime); color: var(--lot-black); }

/* Comparison */
.comparison-section { background: var(--lot-black); padding: 72px 32px; }
.comparison-section__head h2 { font-size: 22px; max-width: 640px; line-height: 1.4; }

.comparison-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  margin-top: 40px;
  border: 2px solid var(--turbo-purple);
}

.comparison-panel {
  background: var(--screen-fog);
  position: relative;
}

.comparison-panel + .comparison-panel { border-left: 4px solid var(--turbo-purple); }

.comparison-panel__head {
  background: var(--turbo-purple);
  color: var(--lot-black);
  font-family: var(--font-heading);
  font-size: 14px;
  text-align: center;
  padding: 12px;
}

.comparison-panel__body { padding: 32px; }
.comparison-panel__body p { margin-bottom: 28px; }

.compare-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 12px 0;
  border-bottom: 1px solid var(--gridline-gray);
  gap: 16px;
}

.compare-row__label {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
}

.compare-row__val {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 20px;
  color: var(--nitro-lime);
}

.comparison-panel .btn--secondary {
  margin-top: 24px;
  width: 100%;
  text-align: center;
}

/* ============= CTA Section ============= */
.cta-block {
  background: var(--turbo-purple);
  padding: 0;
  position: relative;
}

.cta-block__inner {
  text-align: center;
  padding: 80px 32px;
  max-width: 720px;
  margin: 0 auto;
}

.cta-block__inner h2 {
  font-size: 24px;
  color: var(--lot-black);
  line-height: 1.4;
  margin-bottom: 20px;
}

.cta-block__inner p {
  color: var(--lot-black);
  opacity: 0.85;
  margin: 0 auto 32px;
  max-width: 520px;
}

.cta-block__inner .btn--block {
  font-size: 13px;
  padding: 18px 32px;
  min-width: 240px;
}

/* ============= SPECS PAGE ============= */
.specs-header {
  background: var(--lot-black);
  position: relative;
  padding: 64px 32px 48px;
  border-top: 3px solid var(--turbo-purple);
  overflow: hidden;
}

.specs-header::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-conic-gradient(var(--gridline-gray) 0 25%, transparent 0 50%) 0 0 / 24px 24px;
  opacity: 0.30;
  pointer-events: none;
}

.specs-header__inner {
  position: relative;
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 40px;
  align-items: start;
}

.specs-header h1 {
  color: var(--revv-cyan);
  font-size: 28px;
  line-height: 1.5;
  margin: 16px 0 20px;
  text-shadow: 0 0 14px rgba(0,245,255,0.35);
}

.specs-header__strip {
  font-family: var(--font-body);
  color: var(--crt-white);
  font-size: 14px;
  margin-bottom: 24px;
  line-height: 1.8;
}

.specs-header__strip span.sep { color: var(--nitro-lime); margin: 0 8px; }

.specs-header__ctas { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; }

.dashboard-mockup {
  background: var(--screen-fog);
  border: 4px solid var(--turbo-purple);
  box-shadow: 0 0 16px rgba(0,245,255,0.35);
}

.dashboard-mockup__bar {
  background: var(--gridline-gray);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
}

.dashboard-mockup__dot { width: 10px; height: 10px; background: var(--pixel-magenta); }
.dashboard-mockup__dot:nth-child(2) { background: var(--nitro-lime); }
.dashboard-mockup__dot:nth-child(3) { background: var(--revv-cyan); }

.dashboard-mockup__body { padding: 24px; position: relative; }

.dashboard-mockup__title {
  font-family: var(--font-heading);
  font-size: 14px;
  color: var(--revv-cyan);
  margin-bottom: 16px;
  line-height: 1.5;
}

.dashboard-mockup__readout {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.9;
}

.dashboard-mockup__readout span.k { color: var(--gridline-gray); }
.dashboard-mockup__readout span.v { color: var(--crt-white); }

.dashboard-mockup__grade {
  position: absolute;
  top: 16px;
  right: 16px;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.10em;
  background: var(--nitro-lime);
  color: var(--lot-black);
  padding: 4px 8px;
  border: 2px solid var(--lot-black);
}

/* Specs grid */
.specs-grid-section { background: var(--screen-fog); padding: 72px 32px; }
.specs-grid-section__head h2 { color: var(--crt-white); margin: 16px 0 0; }

.specs-grid-section__rule {
  height: 2px;
  background: var(--turbo-purple);
  margin: 24px 0 32px;
}

.specs-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.spec-cell {
  background: var(--lot-black);
  border: 2px solid var(--turbo-purple);
  padding: 24px 20px;
  position: relative;
  transition: border-color .2s ease, box-shadow .2s ease;
}

.spec-cell:hover {
  border-color: var(--revv-cyan);
  box-shadow: 0 0 8px rgba(0,245,255,0.3);
}

.spec-cell__cat {
  font-family: var(--font-accent);
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--turbo-purple);
}

.spec-cell__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  margin-top: 16px;
  margin-bottom: 8px;
}

.spec-cell__val {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--crt-white);
  line-height: 1.6;
}

/* Inspection */
.inspection-section {
  background: var(--lot-black);
  padding: 96px 32px;
  position: relative;
  overflow: hidden;
  text-align: center;
}

.inspection-stamp {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-15deg);
  font-family: var(--font-heading);
  font-size: clamp(80px, 12vw, 140px);
  color: var(--nitro-lime);
  opacity: 0.15;
  pointer-events: none;
  white-space: nowrap;
  z-index: 0;
}

.inspection-section__inner { position: relative; z-index: 1; max-width: 1280px; margin: 0 auto; }
.inspection-section__head .eyebrow { justify-content: center; }
.inspection-section__head h2 { margin-bottom: 16px; }
.inspection-section__head .lead { margin: 0 auto; }

.inspection-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-top: 48px;
  text-align: left;
}

.inspection-card {
  background: var(--screen-fog);
  border: 3px solid var(--nitro-lime);
  padding: 32px 24px;
}

.inspection-card__sys {
  font-family: var(--font-accent);
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--turbo-purple);
  margin-bottom: 16px;
}

.inspection-card__num {
  font-family: var(--font-heading);
  font-size: 22px;
  color: var(--nitro-lime);
  line-height: 1.4;
}

.inspection-card__desc {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.6;
  margin-top: 12px;
}

/* Inspection chart */
.inspection-chart {
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 32px;
  margin: 40px auto 0;
  max-width: 800px;
  text-align: left;
}

.inspection-chart__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  margin-bottom: 20px;
}

.bar-row {
  display: grid;
  grid-template-columns: 130px 1fr 50px;
  align-items: center;
  gap: 16px;
  margin-bottom: 14px;
}

.bar-row__label {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--crt-white);
}

.bar-row__bar {
  height: 16px;
  background: var(--turbo-purple);
  position: relative;
}

.bar-row__fill {
  height: 100%;
  background: var(--revv-cyan);
  display: block;
}

.bar-row__val {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--nitro-lime);
  text-align: right;
}

.inspection-cta { margin-top: 32px; }

/* Vehicle Timeline */
.history-section { background: var(--screen-fog); padding: 80px 32px; }

.history-section .lead { color: var(--revv-cyan); }

.history-rule { height: 2px; background: var(--turbo-purple); margin: 24px 0 32px; }

.history-list {
  border-left: 3px solid var(--turbo-purple);
  margin-left: 12px;
  padding-left: 32px;
}

.history-event {
  position: relative;
  padding: 20px 0;
  border-bottom: 2px solid var(--gridline-gray);
}

.history-event::before {
  content: "";
  position: absolute;
  left: -42px;
  top: 28px;
  width: 16px;
  height: 16px;
  background: var(--nitro-lime);
}

.history-event--current {
  background: var(--screen-fog);
  border: 2px solid var(--revv-cyan);
  padding: 24px;
  box-shadow: 0 0 12px rgba(0,245,255,0.25);
}

.history-event--current::before {
  width: 24px;
  height: 24px;
  border: 2px solid var(--revv-cyan);
  left: -47px;
  top: 28px;
}

.history-event__date {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nitro-lime);
}

.history-event__desc {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--crt-white);
  margin-top: 8px;
  line-height: 1.75;
}

/* Specs CTA close */
.specs-cta-close {
  background: var(--pixel-magenta);
  padding: 96px 32px;
  position: relative;
  text-align: center;
  overflow: hidden;
}

.specs-cta-close::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-conic-gradient(rgba(0,0,0,0.2) 0 25%, transparent 0 50%) 0 0 / 32px 32px;
  opacity: 0.5;
  pointer-events: none;
}

.specs-cta-close__inner { position: relative; max-width: 720px; margin: 0 auto; }

.specs-cta-close h2 {
  color: var(--lot-black);
  font-size: 28px;
  margin-bottom: 16px;
  line-height: 1.4;
}

.specs-cta-close p {
  color: var(--lot-black);
  margin: 0 auto 32px;
  max-width: 560px;
}

.specs-cta-close .btn-row {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.specs-cta-close .btn--block {
  background: var(--lot-black);
  border-color: var(--lot-black);
  color: var(--crt-white);
  box-shadow: 4px 4px 0 rgba(0,0,0,0.4);
}

.specs-cta-close .btn--block:hover { background: var(--revv-cyan); color: var(--lot-black); }

.specs-cta-close .btn--secondary {
  background: transparent;
  border-color: var(--lot-black);
  color: var(--lot-black);
}

.specs-cta-close .btn--secondary:hover { color: var(--revv-cyan); border-color: var(--revv-cyan); }

.specs-cta-close__refund {
  margin-top: 24px;
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--lot-black);
}

.specs-cta-close__refund span.star { color: var(--nitro-lime); }

/* ============= GALLERY PAGE ============= */
.gallery-header {
  background: var(--lot-black);
  padding: 32px 32px 36px;
  border-top: 4px solid;
  border-image: repeating-linear-gradient(90deg, var(--nitro-lime) 0 8px, var(--gridline-gray) 8px 16px) 1;
}

.gallery-header__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 32px;
  align-items: end;
}

.gallery-header h1 { font-size: 28px; line-height: 1.5; }
.gallery-header h1 .punch { color: var(--pixel-magenta); }

.gallery-header__strip {
  font-family: var(--font-body);
  font-size: 14px;
  margin-top: 16px;
  color: var(--crt-white);
}

.gallery-header__strip span.sep { color: var(--revv-cyan); margin: 0 6px; }
.gallery-header__strip .pop { color: var(--pixel-magenta); }

.gallery-header__ctas { display: flex; flex-direction: column; gap: 12px; }

/* Exterior gallery */
.gallery-section {
  background: var(--lot-black);
  position: relative;
  padding: 48px 0;
  overflow: hidden;
}

.gallery-section__head {
  max-width: 1280px;
  margin: 0 auto 32px;
  padding: 0 32px;
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 32px;
  align-items: start;
  position: relative;
  z-index: 1;
}

.gallery-section__head h2 { color: var(--crt-white); margin: 12px 0 12px; max-width: 640px; }
.gallery-section__head p { font-size: 15px; color: rgba(232,240,242,0.75); }

.gallery-watermark {
  position: absolute;
  top: 50%;
  left: 40px;
  transform: translateY(-50%);
  font-family: var(--font-heading);
  font-size: clamp(64px, 10vw, 128px);
  color: var(--turbo-purple);
  opacity: 0.15;
  z-index: 0;
  pointer-events: none;
}

.filmstrip {
  display: flex;
  gap: 12px;
  padding: 0 0 0 80px;
  overflow-x: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--revv-cyan) var(--lot-black);
  position: relative;
  z-index: 1;
}

.filmstrip-tile {
  flex: 0 0 340px;
  height: 260px;
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 12px rgba(0,245,255,0.5);
  position: relative;
}

.filmstrip-tile:hover { box-shadow: 0 0 22px rgba(0,245,255,0.8); }

.filmstrip-tile__overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 64px;
  background: rgba(10,10,10,0.85);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 16px;
}

.filmstrip-tile__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
}

.filmstrip-tile__count {
  background: var(--nitro-lime);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  padding: 4px 8px;
}

.filmstrip-row { padding-bottom: 16px; }

.filmstrip-captions {
  display: grid;
  grid-template-columns: 340px 340px 340px 340px;
  gap: 12px;
  padding: 12px 0 0 80px;
  position: relative;
  z-index: 1;
}

.filmstrip-captions p {
  font-family: var(--font-body);
  font-size: 13px;
  color: rgba(232,240,242,0.7);
  line-height: 1.5;
}

.hotspot-diagram {
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 16px;
  max-width: 320px;
}

.hotspot-diagram__caption {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  margin-top: 12px;
}

/* Interior section (tabs) */
.interior-section {
  background: var(--screen-fog);
  padding: 56px 32px;
}

.interior-section__head { max-width: 1280px; margin: 0 auto 32px; }
.interior-section__head h2 { color: var(--revv-cyan); margin: 12px 0; max-width: 680px; }

.interior-tabs {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 240px 1fr;
  border: 2px solid var(--gridline-gray);
}

.tab-list {
  list-style: none;
  border-right: 1px solid var(--gridline-gray);
}

.tab-button {
  display: block;
  width: 100%;
  text-align: left;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: transparent;
  border: none;
  border-bottom: 1px solid var(--gridline-gray);
  border-left: 2px solid var(--gridline-gray);
  color: rgba(232,240,242,0.5);
  padding: 18px 16px;
  height: 56px;
  cursor: pointer;
}

.tab-button.is-active {
  border-left: 4px solid var(--turbo-purple);
  background: rgba(204,0,255,0.08);
  color: var(--turbo-purple);
}

.tab-content { padding: 28px; display: none; }
.tab-content.is-active { display: block; }

.tab-content__title {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--revv-cyan);
  margin-bottom: 6px;
}

.tab-content__count {
  display: inline-block;
  background: var(--nitro-lime);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  padding: 3px 8px;
  margin-left: 10px;
}

.tab-content__desc {
  font-family: var(--font-body);
  font-size: 14px;
  color: rgba(232,240,242,0.85);
  max-width: 600px;
  margin: 0 0 20px;
}

.tab-photo-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.photo-tile {
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 8px rgba(0,245,255,0.4);
  position: relative;
  height: 165px;
}

.photo-tile__overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(10,10,10,0.8);
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 12px;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--crt-white);
}

.photo-tile__overlay span.view { color: var(--revv-cyan); }

/* Mechanical section */
.mech-section { background: var(--lot-black); padding: 56px 32px; }
.mech-section__inner { max-width: 1280px; margin: 0 auto; }
.mech-section__head h2 { color: var(--crt-white); margin: 12px 0 12px; max-width: 640px; }

.mech-row {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 24px;
  margin-top: 32px;
}

.mech-cat-list { display: flex; flex-direction: column; gap: 16px; }

.mech-cat {
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 16px;
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.mech-cat__icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  color: var(--revv-cyan);
}

.mech-cat__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
}

.mech-cat__count {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--nitro-lime);
  margin-top: 4px;
}

.mech-cat__desc {
  font-family: var(--font-body);
  font-size: 12px;
  color: rgba(232,240,242,0.8);
  margin-top: 4px;
  line-height: 1.5;
}

.mech-photos {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  align-content: start;
}

/* Gallery CTA close */
.gallery-cta {
  background: var(--turbo-purple);
  text-align: center;
  padding: 80px 32px;
  position: relative;
}

.gallery-cta__inner { max-width: 780px; margin: 0 auto; }

.gallery-cta h2 {
  font-size: 32px;
  line-height: 1.4;
  margin-bottom: 12px;
}

.gallery-cta h2 .data { color: var(--nitro-lime); }
.gallery-cta h2 .strike { color: var(--crt-white); position: relative; }

.gallery-cta h2 .strike::after {
  content: "";
  position: absolute;
  left: -2%;
  top: 50%;
  width: 104%;
  height: 6px;
  background: var(--pixel-magenta);
  transform: translateY(-50%);
}

.gallery-cta h2 .closing { color: var(--crt-white); display: block; margin-top: 16px; }

.gallery-cta p {
  font-size: 16px;
  color: rgba(232,240,242,0.85);
  margin: 0 auto 32px;
  max-width: 560px;
}

.gallery-cta__btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

.gallery-cta__btns .btn--lime { box-shadow: 4px 4px 0 var(--lot-black); }

/* ============= RESERVE PAGE ============= */
.reserve-header {
  background: var(--lot-black);
  position: relative;
  padding: 64px 32px 48px;
  overflow: hidden;
  min-height: 480px;
}

.reserve-stamp {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-8deg);
  font-family: var(--font-heading);
  font-size: clamp(60px, 9vw, 120px);
  color: var(--turbo-purple);
  opacity: 0.18;
  white-space: nowrap;
  z-index: 0;
  pointer-events: none;
  letter-spacing: 0.05em;
}

.reserve-header__inner {
  max-width: 1280px;
  margin: 0 auto;
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 40px;
  align-items: start;
}

.reserve-header h1 { font-size: 32px; line-height: 1.5; margin: 12px 0 24px; }

.reserve-header__art {
  align-self: end;
  margin-bottom: -32px;
}

/* Story block */
.story-block {
  background: var(--lot-black);
  padding: 48px 32px;
}

.story-block__frame {
  max-width: 860px;
  margin: 0 auto;
  background: var(--screen-fog);
  border: 2px solid var(--revv-cyan);
}

.story-block__bar {
  background: var(--gridline-gray);
  height: 36px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
}

.story-block__dot { width: 10px; height: 10px; background: var(--pixel-magenta); border-radius: 50%; }
.story-block__dot:nth-child(2) { background: var(--nitro-lime); }
.story-block__dot:nth-child(3) { background: var(--revv-cyan); }

.story-block__body { padding: 28px 32px; }

.story-block__head { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.story-block h2 { font-size: 18px; color: var(--crt-white); line-height: 1.5; margin: 12px 0; }

.story-block__strip {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--nitro-lime);
}

.story-block__badge {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  background: var(--nitro-lime);
  color: var(--lot-black);
  padding: 4px 8px;
  border: 2px solid var(--lot-black);
}

.story-block__body p {
  font-size: 15px;
  color: rgba(232,240,242,0.85);
  margin: 16px 0 24px;
  max-width: 640px;
}

.line-table {
  border-top: 2px solid var(--revv-cyan);
  border-bottom: 2px solid var(--revv-cyan);
  margin-top: 8px;
}

.line-row {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  padding: 14px 0;
  border-bottom: 1px dashed var(--gridline-gray);
  align-items: center;
}

.line-row:last-child { border-bottom: none; }

.line-row__label {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 14px;
  color: var(--crt-white);
}

.line-row__val {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--crt-white);
  text-align: right;
}

.line-row__val--magenta { color: var(--pixel-magenta); font-weight: 700; }
.line-row__val--lime { color: var(--nitro-lime); font-weight: 700; }

/* Contact form */
.contact-section {
  background: var(--screen-fog);
  padding: 64px 32px;
}

.contact-section__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 40px;
  align-items: start;
}

.step-chip {
  display: inline-block;
  background: var(--revv-cyan);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  padding: 4px 8px;
  margin-bottom: 12px;
  border: 2px solid var(--revv-cyan);
}

.contact-section h2 { font-size: 18px; color: var(--crt-white); margin: 16px 0 16px; }

.form-grid { display: flex; flex-direction: column; gap: 20px; margin-top: 24px; }

.form-field label {
  display: block;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
  margin-bottom: 8px;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  background: var(--lot-black);
  border: 2px solid var(--gridline-gray);
  color: var(--crt-white);
  font-family: var(--font-body);
  font-size: 15px;
  padding: 12px 14px;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--revv-cyan);
  outline: none;
  box-shadow: 0 0 8px rgba(0,245,255,0.4);
}

.form-field input::placeholder { color: rgba(46,46,68,1); }

.form-field__hint {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--gridline-gray);
  margin-top: 6px;
}

.radio-row { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }

.radio-row label {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--crt-white);
  cursor: pointer;
  letter-spacing: 0;
  text-transform: none;
  font-weight: 400;
}

.radio-row input[type="radio"] {
  appearance: none;
  width: 14px;
  height: 14px;
  border: 2px solid var(--revv-cyan);
  background: var(--lot-black);
  flex-shrink: 0;
}

.radio-row input[type="radio"]:checked {
  background: var(--revv-cyan);
  box-shadow: inset 0 0 0 2px var(--lot-black);
}

.form-submit {
  margin-top: 24px;
  width: 100%;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--revv-cyan);
  color: var(--lot-black);
  border: 2px solid var(--revv-cyan);
  padding: 16px;
  cursor: pointer;
}

.form-submit:hover { background: var(--nitro-lime); border-color: var(--nitro-lime); }

.trust-sidebar {
  background: var(--screen-fog);
  border: 2px solid var(--turbo-purple);
  padding: 24px;
}

.trust-sidebar__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--turbo-purple);
  margin-bottom: 16px;
}

.trust-list { list-style: none; }
.trust-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--crt-white);
  margin-bottom: 12px;
  line-height: 1.5;
}

.trust-list li::before {
  content: "▣";
  color: var(--nitro-lime);
  font-weight: 700;
  flex-shrink: 0;
}

.secure-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--pixel-magenta);
  color: var(--crt-white);
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  padding: 6px 10px;
  margin-top: 12px;
}

/* Guarantee grid */
.guarantee-section {
  background: var(--turbo-purple);
  padding: 72px 32px;
  text-align: center;
}

.guarantee-section h2 {
  color: var(--lot-black);
  font-size: 26px;
  margin-bottom: 24px;
}

.guarantee-section .eyebrow { justify-content: center; color: var(--lot-black); }
.guarantee-section .eyebrow::before { background: var(--lot-black); }

.guarantee-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 32px;
  max-width: 1000px;
  margin-left: auto;
  margin-right: auto;
}

.guarantee-card {
  background: var(--screen-fog);
  border: 2px solid var(--lot-black);
  padding: 24px;
  text-align: center;
}

.guarantee-card__icon {
  width: 40px;
  height: 40px;
  margin: 0 auto 12px;
  color: var(--revv-cyan);
}

.guarantee-card:nth-child(2n) .guarantee-card__icon { color: var(--nitro-lime); }

.guarantee-card h3 {
  font-size: 12px;
  color: var(--crt-white);
  margin-bottom: 10px;
  line-height: 1.5;
}

.guarantee-card p {
  font-size: 13px;
  color: rgba(232,240,242,0.8);
  line-height: 1.6;
}

/* FAQ */
.faq-section {
  background: var(--lot-black);
  padding: 80px 32px 0;
}

.faq-section__inner {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}

.faq-section__inner .eyebrow { justify-content: center; }

.faq-section h2 {
  color: var(--crt-white);
  font-size: 18px;
  margin-bottom: 32px;
  line-height: 1.6;
}

.faq-section h2 .price { color: var(--revv-cyan); }

.faq-list {
  border-top: 1px solid var(--gridline-gray);
  text-align: left;
}

.faq-row {
  border-bottom: 1px solid var(--gridline-gray);
}

.faq-row__btn {
  display: flex;
  width: 100%;
  background: transparent;
  border: none;
  padding: 18px 16px;
  cursor: pointer;
  align-items: center;
  justify-content: space-between;
  text-align: left;
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 16px;
  color: var(--crt-white);
}

.faq-row__btn .toggle {
  font-family: var(--font-heading);
  color: var(--revv-cyan);
  font-size: 14px;
}

.faq-row__answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height .3s ease, padding .3s ease;
  font-family: var(--font-body);
  font-size: 15px;
  color: rgba(232,240,242,0.85);
  line-height: 1.75;
}

.faq-row.is-open {
  background: var(--screen-fog);
  border-left: 4px solid var(--revv-cyan);
}

.faq-row.is-open .faq-row__answer {
  max-height: 320px;
  padding: 0 16px 18px;
}

.faq-row.is-open .toggle { color: var(--nitro-lime); }

/* Final CTA strip */
.final-cta-strip {
  background: var(--revv-cyan);
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 0;
}

.final-cta-strip__btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--lot-black);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 16px 32px;
  border: 2px solid var(--lot-black);
  width: 280px;
  height: 52px;
  justify-content: center;
}

.final-cta-strip__btn { color: var(--crt-white); }
.final-cta-strip__btn:hover { background: var(--nitro-lime); color: var(--lot-black); text-decoration: none; }

.final-cta-strip__btn svg { width: 14px; height: 14px; flex-shrink: 0; }

/* ============= UTILITIES ============= */
.section-cap-purple {
  height: 8px;
  background: var(--turbo-purple);
}

.cap--lime-checker {
  height: 16px;
  background:
    repeating-conic-gradient(var(--nitro-lime) 0 25%, var(--lot-black) 0 50%) 0 0 / 16px 16px;
}

/* ============= RESPONSIVE ============= */
@media (max-width: 1100px) {
  .hero__inner { grid-template-columns: 1fr; }
  .hero__title { font-size: 44px; }
  .feature-grid-layout { grid-template-columns: 1fr; }
  .feature-grid-text { border-right: none; padding-right: 0; }
  .item-grid { grid-template-columns: repeat(2, 1fr); }
  .stat-row { grid-template-columns: repeat(2, 1fr); }
  .testimonial-grid { grid-template-columns: 1fr 1fr; }
  .testimonial-card:nth-child(3) { transform: translateY(0); grid-column: span 2; }
  .filter-grid { grid-template-columns: repeat(2, 1fr); }
  .specs-grid { grid-template-columns: repeat(2, 1fr); }
  .inspection-grid { grid-template-columns: repeat(2, 1fr); }
  .guarantee-grid { grid-template-columns: repeat(2, 1fr); }
  .specs-header__inner { grid-template-columns: 1fr; }
  .reserve-header__inner { grid-template-columns: 1fr; }
  .gallery-header__inner { grid-template-columns: 1fr; }
  .contact-section__inner { grid-template-columns: 1fr; }
  .timeline-row { grid-template-columns: repeat(2, 1fr); }
  .timeline-row::before { display: none; }
  .mech-row { grid-template-columns: 1fr; }
  .mech-photos { grid-template-columns: repeat(3, 1fr); }
  .interior-tabs { grid-template-columns: 1fr; }
  .tab-list { display: flex; flex-wrap: wrap; border-right: none; }
  .tab-button { flex: 1; min-width: 50%; }
  .comparison-row { grid-template-columns: 1fr; }
  .comparison-panel + .comparison-panel { border-left: none; border-top: 4px solid var(--turbo-purple); }
  .gallery-section__head { grid-template-columns: 1fr; }
}

@media (max-width: 700px) {
  .nav__links { display: none; }
  .section { padding: 48px 20px; }
  h1 { font-size: 24px; }
  h2 { font-size: 18px; }
  .hero { padding: 48px 20px; }
  .hero__title { font-size: 28px; }
  .hero__title-line-1 { margin-right: -40px; }
  .item-grid-headline { font-size: 32px; }
  .stat-row { grid-template-columns: 1fr 1fr; }
  .feature-grid { grid-template-columns: 1fr; }
  .item-grid { grid-template-columns: 1fr; }
  .specs-grid { grid-template-columns: 1fr; }
  .inspection-grid { grid-template-columns: 1fr 1fr; }
  .guarantee-grid { grid-template-columns: 1fr 1fr; }
  .testimonial-grid { grid-template-columns: 1fr; }
  .testimonial-card:nth-child(2),
  .testimonial-card:nth-child(3) { transform: translateY(0); grid-column: 1; }
  .filter-grid { grid-template-columns: 1fr; }
  .timeline-row { grid-template-columns: 1fr; }
  .footer__inner { grid-template-columns: 1fr 1fr; }
  .footer__brand { grid-column: span 2; }
  .filmstrip-captions { grid-template-columns: 1fr; padding-left: 20px; }
  .filmstrip { padding-left: 20px; }
  .mech-photos { grid-template-columns: repeat(2, 1fr); }
}

tool_use_result.content:
/* ==========================================================================
   RevvLot — Retro 90s Web Used Car Marketplace
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=IBM+Plex+Mono:wght@400;500;700&family=Archivo:wght@700;900&display=swap');

:root {
  --lot-black: #0A0A0A;
  --revv-cyan: #00F5FF;
  --turbo-purple: #CC00FF;
  --nitro-lime: #AAFF00;
  --screen-fog: #1C1C2E;
  --pixel-magenta: #FF2D78;
  --crt-white: #E8F0F2;
  --gridline-gray: #2E2E44;
  --font-heading: 'Press Start 2P', monospace;
  --font-body: 'IBM Plex Mono', monospace;
  --font-accent: 'Archivo', sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--lot-black);
  color: var(--crt-white);
  line-height: 1.75;
  font-size: 15px;
  overflow-x: hidden;
  background-image:
    repeating-linear-gradient(0deg, rgba(46,46,68,0.05) 0 1px, transparent 1px 4px),
    repeating-linear-gradient(90deg, rgba(46,46,68,0.05) 0 1px, transparent 1px 4px);
}

a { color: var(--revv-cyan); text-decoration: none; }
a:hover { text-decoration: underline; }

img, svg { max-width: 100%; display: block; }

/* ============= NAV ============= */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--lot-black);
  border-bottom: 2px solid var(--turbo-purple);
}

.nav__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 32px;
  gap: 24px;
}

.nav__brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-heading);
  font-size: 16px;
  color: var(--revv-cyan);
  text-shadow: 0 0 8px rgba(0,245,255,0.45);
}

.nav__brand-mark {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
}

.nav__links {
  display: flex;
  gap: 4px;
  list-style: none;
}

.nav__links a {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
  padding: 8px 12px;
  border: 2px solid transparent;
  display: inline-block;
}

.nav__links a:hover,
.nav__links a.is-active {
  color: var(--revv-cyan);
  border-color: var(--revv-cyan);
  text-decoration: none;
}

.nav__cta {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--revv-cyan);
  color: var(--lot-black);
  padding: 10px 18px;
  border: 2px solid var(--revv-cyan);
  box-shadow: 4px 4px 0 var(--turbo-purple);
}

.nav__cta:hover { text-decoration: none; background: var(--nitro-lime); border-color: var(--nitro-lime); }

/* ============= BUTTONS ============= */
.btn {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 14px 28px;
  border: 3px solid var(--revv-cyan);
  background: var(--revv-cyan);
  color: var(--lot-black);
  display: inline-block;
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--lot-black);
  transition: transform .15s ease, box-shadow .15s ease;
}

.btn:hover {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--lot-black);
  text-decoration: none;
  background: var(--nitro-lime);
  border-color: var(--nitro-lime);
}

.btn--secondary {
  background: transparent;
  color: var(--crt-white);
  border-color: var(--crt-white);
  box-shadow: 4px 4px 0 var(--gridline-gray);
}

.btn--secondary:hover {
  background: transparent;
  color: var(--revv-cyan);
  border-color: var(--revv-cyan);
}

.btn--purple {
  background: var(--turbo-purple);
  color: var(--crt-white);
  border-color: var(--turbo-purple);
}

.btn--purple:hover {
  background: var(--pixel-magenta);
  border-color: var(--pixel-magenta);
  color: var(--crt-white);
}

.btn--lime {
  background: var(--nitro-lime);
  border-color: var(--lot-black);
  color: var(--lot-black);
}

.btn--block {
  background: var(--lot-black);
  border-color: var(--lot-black);
  color: var(--crt-white);
}

.btn--block:hover {
  background: var(--revv-cyan);
  border-color: var(--lot-black);
  color: var(--lot-black);
}

/* ============= EYEBROW ============= */
.eyebrow {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
}

.eyebrow::before {
  content: "";
  width: 32px;
  height: 2px;
  background: currentColor;
  display: inline-block;
}

.eyebrow--lime { color: var(--nitro-lime); }
.eyebrow--purple { color: var(--turbo-purple); }
.eyebrow--magenta { color: var(--pixel-magenta); }
.eyebrow--black { color: var(--lot-black); }

/* ============= TYPOGRAPHY ============= */
h1, h2, h3, h4 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  line-height: 1.3;
  letter-spacing: 0;
  color: var(--crt-white);
}

h1 { font-size: 36px; }
h2 { font-size: 24px; }
h3 { font-size: 14px; }

p { font-family: var(--font-body); }

.lead {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--crt-white);
  max-width: 560px;
  line-height: 1.75;
}

/* ============= LAYOUT ============= */
.section {
  padding: 80px 32px;
  position: relative;
  overflow: hidden;
}

.container {
  max-width: 1280px;
  margin: 0 auto;
  width: 100%;
}

.section--screen { background: var(--screen-fog); }
.section--purple { background: var(--turbo-purple); }
.section--magenta { background: var(--pixel-magenta); }

/* ============= STRUCTURAL DIVIDERS ============= */
.purple-rule {
  height: 8px;
  width: 100%;
  background:
    repeating-linear-gradient(90deg, var(--turbo-purple) 0 8px, var(--lot-black) 8px 10px);
}

.checker-strip {
  height: 16px;
  background:
    repeating-conic-gradient(var(--nitro-lime) 0 25%, var(--lot-black) 0 50%) 0 0 / 16px 16px;
}

.checker-strip--gray {
  background:
    repeating-conic-gradient(var(--gridline-gray) 0 25%, var(--lot-black) 0 50%) 0 0 / 16px 16px;
}

.checker-strip--magenta {
  background:
    repeating-conic-gradient(var(--pixel-magenta) 0 25%, #c2225f 0 50%) 0 0 / 16px 16px;
}

/* ============= HOME — HERO ============= */
.hero {
  background: var(--lot-black);
  padding: 80px 32px 60px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(45deg, rgba(46,46,68,0.4) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(46,46,68,0.4) 25%, transparent 25%);
  background-size: 8px 8px;
  opacity: 0.07;
  pointer-events: none;
}

.hero__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 24px;
  position: relative;
  align-items: center;
}

.hero__title {
  font-size: 64px;
  line-height: 1.1;
  margin-top: 16px;
  margin-bottom: 24px;
  position: relative;
  z-index: 3;
}

.hero__title-line-1 {
  color: var(--revv-cyan);
  display: block;
  white-space: nowrap;
  margin-right: -160px;
  text-shadow:
    4px 4px 0 var(--lot-black),
    0 0 18px rgba(0,245,255,0.35);
}

.hero__title-line-2 {
  color: var(--crt-white);
  display: block;
}

.hero__lead {
  margin-bottom: 32px;
}

.hero__ctas { display: flex; gap: 16px; flex-wrap: wrap; }

.hero__visual {
  position: relative;
  z-index: 1;
}

.browser-frame {
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 24px rgba(0,245,255,0.25);
}

.browser-frame__bar {
  background: var(--gridline-gray);
  border-bottom: 2px solid var(--revv-cyan);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
}

.browser-frame__dot {
  width: 12px;
  height: 12px;
  background: var(--pixel-magenta);
}
.browser-frame__dot:nth-child(2) { background: var(--nitro-lime); }
.browser-frame__dot:nth-child(3) { background: var(--revv-cyan); }

.browser-frame__url {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--crt-white);
  background: var(--lot-black);
  padding: 4px 12px;
  margin-left: 12px;
  flex: 1;
  border: 1px solid var(--gridline-gray);
}

.browser-frame__body { padding: 0; }

/* ============= STATS SECTION ============= */
.stats {
  background: var(--screen-fog);
  position: relative;
  padding: 56px 32px;
}

.stats::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-conic-gradient(var(--gridline-gray) 0 25%, transparent 0 50%) 0 0 / 16px 16px;
  opacity: 0.5;
  pointer-events: none;
}

.stats__inner { position: relative; }

.stats__head { margin-bottom: 32px; }

.stat-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 2px solid var(--revv-cyan);
}

.stat-card {
  padding: 28px 20px 20px 28px;
  border-right: 1px solid var(--gridline-gray);
  position: relative;
}

.stat-card:last-child { border-right: none; }

.stat-card__cat {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gridline-gray);
  margin-bottom: 12px;
}

.stat-card__num {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 48px;
  color: var(--nitro-lime);
  line-height: 1;
  text-shadow: 0 0 12px rgba(170,255,0,0.35);
}

.stat-card__desc {
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.6;
  margin-top: 12px;
}

/* ============= FEATURE GRID (HOME) ============= */
.feature-grid-section {
  background: var(--lot-black);
}

.feature-grid-layout {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 32px;
  align-items: start;
}

.feature-grid-text {
  border-right: 2px solid var(--turbo-purple);
  padding-right: 32px;
}

.feature-grid-text h2 {
  font-size: 18px;
  line-height: 1.5;
  margin-bottom: 16px;
}

.feature-grid-text p { margin-bottom: 24px; max-width: none; }

.feature-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.feature-card {
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 28px;
  position: relative;
  transition: border-color .2s ease, box-shadow .2s ease;
}

.feature-card:hover {
  border-color: var(--revv-cyan);
  box-shadow: 0 0 18px rgba(0,245,255,0.2);
}

.feature-card::after {
  content: "";
  position: absolute;
  bottom: 8px;
  right: 8px;
  width: 4px;
  height: 4px;
  background: var(--turbo-purple);
}

.feature-card:nth-child(4) { transform: translateY(16px); }

.feature-card__icon {
  width: 40px;
  height: 40px;
  margin-bottom: 16px;
  color: var(--revv-cyan);
}

.feature-card h3 {
  font-size: 12px;
  margin-bottom: 12px;
  line-height: 1.5;
}

.feature-card p {
  font-size: 13px;
  line-height: 1.7;
}

/* ============= TIMELINE (HOME) ============= */
.timeline-section { background: var(--lot-black); }

.timeline-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 40px;
  position: relative;
}

.timeline-row::before {
  content: "";
  position: absolute;
  top: 24px;
  left: 24px;
  right: 24px;
  height: 0;
  border-top: 2px dashed var(--revv-cyan);
  z-index: 0;
}

.timeline-step { position: relative; }

.timeline-node {
  width: 48px;
  height: 48px;
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 20px;
  color: var(--nitro-lime);
  position: relative;
  z-index: 1;
  margin-bottom: 20px;
}

.timeline-step__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  margin-bottom: 8px;
}

.timeline-step__desc {
  font-size: 14px;
  color: var(--crt-white);
  line-height: 1.7;
}

.timeline-cta {
  text-align: center;
  margin-top: 48px;
}

/* ============= TESTIMONIALS ============= */
.testimonials {
  background: var(--turbo-purple);
  padding: 80px 32px;
}

.testimonials__head h2 { color: var(--lot-black); }

.testimonial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
  align-items: start;
}

.testimonial-card {
  background: var(--lot-black);
  border: 2px solid var(--crt-white);
  padding: 28px;
  position: relative;
}

.testimonial-card:nth-child(2) { transform: translateY(32px); }
.testimonial-card:nth-child(3) { transform: translateY(48px); }

.testimonial-card__quote {
  position: absolute;
  top: -28px;
  left: 16px;
  font-family: var(--font-body);
  font-size: 64px;
  color: var(--nitro-lime);
  line-height: 1;
  text-shadow: 0 0 14px rgba(170,255,0,0.5);
}

.testimonial-card__text {
  font-size: 14px;
  color: var(--crt-white);
  line-height: 1.75;
  margin-top: 8px;
}

.testimonial-card__attr {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  margin-top: 16px;
}

.testimonial-card__sticker {
  position: absolute;
  bottom: -14px;
  right: -10px;
  background: var(--pixel-magenta);
  color: var(--crt-white);
  border: 3px solid var(--pixel-magenta);
  padding: 6px 10px;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.08em;
  transform: rotate(4deg);
  box-shadow: 3px 3px 0 var(--lot-black);
}

/* ============= FOOTER ============= */
.footer {
  background: var(--lot-black);
  border-top: 4px solid var(--revv-cyan);
  padding: 48px 32px 32px;
  color: var(--crt-white);
}

.footer__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 32px;
}

.footer h4 {
  font-size: 11px;
  color: var(--nitro-lime);
  margin-bottom: 16px;
}

.footer ul { list-style: none; }
.footer li { margin-bottom: 8px; font-size: 13px; }
.footer a { color: var(--crt-white); }
.footer a:hover { color: var(--revv-cyan); }

.footer__brand {
  font-family: var(--font-heading);
  color: var(--revv-cyan);
  font-size: 18px;
  margin-bottom: 16px;
}

.footer__copy {
  max-width: 1280px;
  margin: 32px auto 0;
  padding-top: 16px;
  border-top: 1px solid var(--gridline-gray);
  font-size: 12px;
  color: var(--gridline-gray);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

/* ============= PRODUCT PAGE ============= */
.page-header-masthead {
  position: relative;
  background: var(--lot-black);
  padding: 96px 32px 56px;
  overflow: hidden;
  min-height: 320px;
}

.page-header-masthead::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("assets/car-pattern.svg");
  background-size: 80px 80px;
  opacity: 0.18;
  pointer-events: none;
}

.page-header-masthead h1 { font-size: 32px; line-height: 1.4; margin-bottom: 20px; }
.page-header-masthead .lead { color: rgba(232,240,242,0.8); }
.page-header-masthead__inner { position: relative; max-width: 1280px; margin: 0 auto; }

.filter-section {
  background: var(--screen-fog);
  padding: 48px 32px;
}

.filter-section__head { max-width: 1280px; margin: 0 auto 24px; }
.filter-section__head h2 { color: var(--revv-cyan); margin-bottom: 12px; }
.filter-section__head p { font-size: 15px; max-width: 600px; }

.filter-window {
  max-width: 1280px;
  margin: 0 auto;
  background: var(--lot-black);
  border: 2px solid var(--revv-cyan);
}

.filter-window__bar {
  background: var(--gridline-gray);
  height: 32px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  border-bottom: 2px solid var(--revv-cyan);
  position: relative;
}

.filter-window__dot {
  width: 10px;
  height: 10px;
  background: var(--pixel-magenta);
}
.filter-window__dot:nth-child(2) { background: var(--nitro-lime); }
.filter-window__dot:nth-child(3) { background: var(--revv-cyan); }

.filter-window__label {
  font-family: var(--font-body);
  font-size: 11px;
  color: var(--crt-white);
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  letter-spacing: 0.05em;
}

.filter-window__body { padding: 28px; }

.filter-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 24px;
}

.filter-field label {
  display: block;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
  margin-bottom: 8px;
}

.filter-field input[type="text"] {
  width: 100%;
  background: var(--lot-black);
  border: 2px solid var(--revv-cyan);
  color: var(--crt-white);
  font-family: var(--font-body);
  font-size: 14px;
  padding: 10px 12px;
}

.filter-field input::placeholder { color: var(--gridline-gray); }

.range-bar {
  position: relative;
  height: 12px;
  background: var(--gridline-gray);
  margin: 14px 0 8px;
}

.range-bar__fill {
  position: absolute;
  top: 0;
  left: 25%;
  right: 25%;
  height: 100%;
  background: var(--revv-cyan);
}

.range-bar--purple .range-bar__fill { background: var(--turbo-purple); }

.range-bar__handle {
  position: absolute;
  top: -2px;
  width: 12px;
  height: 16px;
  background: var(--nitro-lime);
}

.range-bar__handle--left { left: calc(25% - 6px); }
.range-bar__handle--right { right: calc(25% - 6px); }

.range-labels {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--crt-white);
}

.chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  background: var(--gridline-gray);
  border: 2px solid var(--gridline-gray);
  color: var(--crt-white);
  padding: 6px 10px;
}

.chip.is-active {
  border-color: var(--revv-cyan);
  color: var(--revv-cyan);
  background: rgba(0,245,255,0.06);
}

.filter-search-btn {
  width: 100%;
  height: 48px;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--revv-cyan);
  color: var(--lot-black);
  border: 2px solid var(--lot-black);
  cursor: pointer;
}

.filter-search-btn:hover { background: var(--nitro-lime); }

/* Item Grid */
.item-grid-section {
  background: var(--lot-black);
  padding: 72px 0 64px;
  overflow: hidden;
}

.item-grid-head {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 32px;
}

.item-grid-headline {
  font-size: 64px;
  white-space: nowrap;
  color: var(--revv-cyan);
  margin: 16px 0 8px -10px;
  text-shadow: 4px 4px 0 var(--lot-black), 0 0 18px rgba(0,245,255,0.35);
  width: max-content;
}

.item-grid-head .purple-line {
  height: 4px;
  background: var(--turbo-purple);
  width: 100vw;
  margin-left: -32px;
  margin-bottom: 0;
}

.item-grid-head .lead {
  color: rgba(232,240,242,0.7);
  margin-top: 20px;
  font-size: 14px;
}

.item-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px 16px;
  max-width: 1280px;
  margin: 40px auto 0;
  padding: 0 32px;
}

.item-card {
  background: var(--screen-fog);
  border: 2px solid var(--revv-cyan);
  position: relative;
  padding: 28px 20px 16px;
  display: flex;
  flex-direction: column;
}

.item-card__badge {
  position: absolute;
  top: -10px;
  left: -10px;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 9px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  background: var(--nitro-lime);
  color: var(--lot-black);
  padding: 6px 10px;
  border: 2px solid var(--lot-black);
  box-shadow: 3px 3px 0 var(--lot-black);
  z-index: 2;
}

.item-card__badge--cyan { background: var(--revv-cyan); }
.item-card__badge--magenta { background: var(--pixel-magenta); color: var(--crt-white); }
.item-card__badge--purple { background: var(--turbo-purple); color: var(--crt-white); }
.item-card__badge--gray { background: var(--gridline-gray); color: var(--crt-white); }

.item-card__title {
  font-family: var(--font-heading);
  font-size: 13px;
  color: var(--crt-white);
  margin-bottom: 6px;
  line-height: 1.5;
}

.item-card__price {
  font-family: var(--font-heading);
  font-size: 13px;
  color: var(--nitro-lime);
  margin-bottom: 12px;
}

.item-card__specs {
  font-family: var(--font-body);
  font-size: 12px;
  color: rgba(232,240,242,0.85);
  margin-bottom: 8px;
}

.item-card__status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-body);
  font-size: 11px;
  color: var(--crt-white);
  margin-bottom: 12px;
}

.item-card__status::before {
  content: "";
  width: 8px;
  height: 8px;
  background: var(--nitro-lime);
  border-radius: 50%;
  display: inline-block;
}

.item-card__loc {
  display: inline-block;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  background: var(--gridline-gray);
  color: var(--crt-white);
  padding: 4px 8px;
  margin-bottom: 12px;
  width: fit-content;
}

.item-card__divider {
  border-top: 1px solid var(--gridline-gray);
  margin: 8px 0 12px;
}

.item-card__cta-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: auto;
}

.item-card__cta-row a {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  text-align: center;
  padding: 10px 8px;
  border: 2px solid var(--revv-cyan);
  color: var(--revv-cyan);
}

.item-card__cta-row a:first-child { background: transparent; }
.item-card__cta-row a:last-child { background: var(--revv-cyan); color: var(--lot-black); }
.item-card__cta-row a:hover { text-decoration: none; background: var(--nitro-lime); border-color: var(--nitro-lime); color: var(--lot-black); }

/* Comparison */
.comparison-section { background: var(--lot-black); padding: 72px 32px; }
.comparison-section__head h2 { font-size: 22px; max-width: 640px; line-height: 1.4; }

.comparison-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  margin-top: 40px;
  border: 2px solid var(--turbo-purple);
}

.comparison-panel {
  background: var(--screen-fog);
  position: relative;
}

.comparison-panel + .comparison-panel { border-left: 4px solid var(--turbo-purple); }

.comparison-panel__head {
  background: var(--turbo-purple);
  color: var(--lot-black);
  font-family: var(--font-heading);
  font-size: 14px;
  text-align: center;
  padding: 12px;
}

.comparison-panel__body { padding: 32px; }
.comparison-panel__body p { margin-bottom: 28px; }

.compare-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 12px 0;
  border-bottom: 1px solid var(--gridline-gray);
  gap: 16px;
}

.compare-row__label {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
}

.compare-row__val {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 20px;
  color: var(--nitro-lime);
}

.comparison-panel .btn--secondary {
  margin-top: 24px;
  width: 100%;
  text-align: center;
}

/* ============= CTA Section ============= */
.cta-block {
  background: var(--turbo-purple);
  padding: 0;
  position: relative;
}

.cta-block__inner {
  text-align: center;
  padding: 80px 32px;
  max-width: 720px;
  margin: 0 auto;
}

.cta-block__inner h2 {
  font-size: 24px;
  color: var(--lot-black);
  line-height: 1.4;
  margin-bottom: 20px;
}

.cta-block__inner p {
  color: var(--lot-black);
  opacity: 0.85;
  margin: 0 auto 32px;
  max-width: 520px;
}

.cta-block__inner .btn--block {
  font-size: 13px;
  padding: 18px 32px;
  min-width: 240px;
}

/* ============= SPECS PAGE ============= */
.specs-header {
  background: var(--lot-black);
  position: relative;
  padding: 64px 32px 48px;
  border-top: 3px solid var(--turbo-purple);
  overflow: hidden;
}

.specs-header::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-conic-gradient(var(--gridline-gray) 0 25%, transparent 0 50%) 0 0 / 24px 24px;
  opacity: 0.30;
  pointer-events: none;
}

.specs-header__inner {
  position: relative;
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 40px;
  align-items: start;
}

.specs-header h1 {
  color: var(--revv-cyan);
  font-size: 28px;
  line-height: 1.5;
  margin: 16px 0 20px;
  text-shadow: 0 0 14px rgba(0,245,255,0.35);
}

.specs-header__strip {
  font-family: var(--font-body);
  color: var(--crt-white);
  font-size: 14px;
  margin-bottom: 24px;
  line-height: 1.8;
}

.specs-header__strip span.sep { color: var(--nitro-lime); margin: 0 8px; }

.specs-header__ctas { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; }

.dashboard-mockup {
  background: var(--screen-fog);
  border: 4px solid var(--turbo-purple);
  box-shadow: 0 0 16px rgba(0,245,255,0.35);
}

.dashboard-mockup__bar {
  background: var(--gridline-gray);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
}

.dashboard-mockup__dot { width: 10px; height: 10px; background: var(--pixel-magenta); }
.dashboard-mockup__dot:nth-child(2) { background: var(--nitro-lime); }
.dashboard-mockup__dot:nth-child(3) { background: var(--revv-cyan); }

.dashboard-mockup__body { padding: 24px; position: relative; }

.dashboard-mockup__title {
  font-family: var(--font-heading);
  font-size: 14px;
  color: var(--revv-cyan);
  margin-bottom: 16px;
  line-height: 1.5;
}

.dashboard-mockup__readout {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.9;
}

.dashboard-mockup__readout span.k { color: var(--gridline-gray); }
.dashboard-mockup__readout span.v { color: var(--crt-white); }

.dashboard-mockup__grade {
  position: absolute;
  top: 16px;
  right: 16px;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.10em;
  background: var(--nitro-lime);
  color: var(--lot-black);
  padding: 4px 8px;
  border: 2px solid var(--lot-black);
}

/* Specs grid */
.specs-grid-section { background: var(--screen-fog); padding: 72px 32px; }
.specs-grid-section__head h2 { color: var(--crt-white); margin: 16px 0 0; }

.specs-grid-section__rule {
  height: 2px;
  background: var(--turbo-purple);
  margin: 24px 0 32px;
}

.specs-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.spec-cell {
  background: var(--lot-black);
  border: 2px solid var(--turbo-purple);
  padding: 24px 20px;
  position: relative;
  transition: border-color .2s ease, box-shadow .2s ease;
}

.spec-cell:hover {
  border-color: var(--revv-cyan);
  box-shadow: 0 0 8px rgba(0,245,255,0.3);
}

.spec-cell__cat {
  font-family: var(--font-accent);
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--turbo-purple);
}

.spec-cell__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  margin-top: 16px;
  margin-bottom: 8px;
}

.spec-cell__val {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--crt-white);
  line-height: 1.6;
}

/* Inspection */
.inspection-section {
  background: var(--lot-black);
  padding: 96px 32px;
  position: relative;
  overflow: hidden;
  text-align: center;
}

.inspection-stamp {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-15deg);
  font-family: var(--font-heading);
  font-size: clamp(80px, 12vw, 140px);
  color: var(--nitro-lime);
  opacity: 0.15;
  pointer-events: none;
  white-space: nowrap;
  z-index: 0;
}

.inspection-section__inner { position: relative; z-index: 1; max-width: 1280px; margin: 0 auto; }
.inspection-section__head .eyebrow { justify-content: center; }
.inspection-section__head h2 { margin-bottom: 16px; }
.inspection-section__head .lead { margin: 0 auto; }

.inspection-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-top: 48px;
  text-align: left;
}

.inspection-card {
  background: var(--screen-fog);
  border: 3px solid var(--nitro-lime);
  padding: 32px 24px;
}

.inspection-card__sys {
  font-family: var(--font-accent);
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--turbo-purple);
  margin-bottom: 16px;
}

.inspection-card__num {
  font-family: var(--font-heading);
  font-size: 22px;
  color: var(--nitro-lime);
  line-height: 1.4;
}

.inspection-card__desc {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--crt-white);
  line-height: 1.6;
  margin-top: 12px;
}

/* Inspection chart */
.inspection-chart {
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 32px;
  margin: 40px auto 0;
  max-width: 800px;
  text-align: left;
}

.inspection-chart__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  margin-bottom: 20px;
}

.bar-row {
  display: grid;
  grid-template-columns: 130px 1fr 50px;
  align-items: center;
  gap: 16px;
  margin-bottom: 14px;
}

.bar-row__label {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--crt-white);
}

.bar-row__bar {
  height: 16px;
  background: var(--turbo-purple);
  position: relative;
}

.bar-row__fill {
  height: 100%;
  background: var(--revv-cyan);
  display: block;
}

.bar-row__val {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--nitro-lime);
  text-align: right;
}

.inspection-cta { margin-top: 32px; }

/* Vehicle Timeline */
.history-section { background: var(--screen-fog); padding: 80px 32px; }

.history-section .lead { color: var(--revv-cyan); }

.history-rule { height: 2px; background: var(--turbo-purple); margin: 24px 0 32px; }

.history-list {
  border-left: 3px solid var(--turbo-purple);
  margin-left: 12px;
  padding-left: 32px;
}

.history-event {
  position: relative;
  padding: 20px 0;
  border-bottom: 2px solid var(--gridline-gray);
}

.history-event::before {
  content: "";
  position: absolute;
  left: -42px;
  top: 28px;
  width: 16px;
  height: 16px;
  background: var(--nitro-lime);
}

.history-event--current {
  background: var(--screen-fog);
  border: 2px solid var(--revv-cyan);
  padding: 24px;
  box-shadow: 0 0 12px rgba(0,245,255,0.25);
}

.history-event--current::before {
  width: 24px;
  height: 24px;
  border: 2px solid var(--revv-cyan);
  left: -47px;
  top: 28px;
}

.history-event__date {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nitro-lime);
}

.history-event__desc {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--crt-white);
  margin-top: 8px;
  line-height: 1.75;
}

/* Specs CTA close */
.specs-cta-close {
  background: var(--pixel-magenta);
  padding: 96px 32px;
  position: relative;
  text-align: center;
  overflow: hidden;
}

.specs-cta-close::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-conic-gradient(rgba(0,0,0,0.2) 0 25%, transparent 0 50%) 0 0 / 32px 32px;
  opacity: 0.5;
  pointer-events: none;
}

.specs-cta-close__inner { position: relative; max-width: 720px; margin: 0 auto; }

.specs-cta-close h2 {
  color: var(--lot-black);
  font-size: 28px;
  margin-bottom: 16px;
  line-height: 1.4;
}

.specs-cta-close p {
  color: var(--lot-black);
  margin: 0 auto 32px;
  max-width: 560px;
}

.specs-cta-close .btn-row {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.specs-cta-close .btn--block {
  background: var(--lot-black);
  border-color: var(--lot-black);
  color: var(--crt-white);
  box-shadow: 4px 4px 0 rgba(0,0,0,0.4);
}

.specs-cta-close .btn--block:hover { background: var(--revv-cyan); color: var(--lot-black); }

.specs-cta-close .btn--secondary {
  background: transparent;
  border-color: var(--lot-black);
  color: var(--lot-black);
}

.specs-cta-close .btn--secondary:hover { color: var(--revv-cyan); border-color: var(--revv-cyan); }

.specs-cta-close__refund {
  margin-top: 24px;
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--lot-black);
}

.specs-cta-close__refund span.star { color: var(--nitro-lime); }

/* ============= GALLERY PAGE ============= */
.gallery-header {
  background: var(--lot-black);
  padding: 32px 32px 36px;
  border-top: 4px solid;
  border-image: repeating-linear-gradient(90deg, var(--nitro-lime) 0 8px, var(--gridline-gray) 8px 16px) 1;
}

.gallery-header__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 32px;
  align-items: end;
}

.gallery-header h1 { font-size: 28px; line-height: 1.5; }
.gallery-header h1 .punch { color: var(--pixel-magenta); }

.gallery-header__strip {
  font-family: var(--font-body);
  font-size: 14px;
  margin-top: 16px;
  color: var(--crt-white);
}

.gallery-header__strip span.sep { color: var(--revv-cyan); margin: 0 6px; }
.gallery-header__strip .pop { color: var(--pixel-magenta); }

.gallery-header__ctas { display: flex; flex-direction: column; gap: 12px; }

/* Exterior gallery */
.gallery-section {
  background: var(--lot-black);
  position: relative;
  padding: 48px 0;
  overflow: hidden;
}

.gallery-section__head {
  max-width: 1280px;
  margin: 0 auto 32px;
  padding: 0 32px;
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 32px;
  align-items: start;
  position: relative;
  z-index: 1;
}

.gallery-section__head h2 { color: var(--crt-white); margin: 12px 0 12px; max-width: 640px; }
.gallery-section__head p { font-size: 15px; color: rgba(232,240,242,0.75); }

.gallery-watermark {
  position: absolute;
  top: 50%;
  left: 40px;
  transform: translateY(-50%);
  font-family: var(--font-heading);
  font-size: clamp(64px, 10vw, 128px);
  color: var(--turbo-purple);
  opacity: 0.15;
  z-index: 0;
  pointer-events: none;
}

.filmstrip {
  display: flex;
  gap: 12px;
  padding: 0 0 0 80px;
  overflow-x: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--revv-cyan) var(--lot-black);
  position: relative;
  z-index: 1;
}

.filmstrip-tile {
  flex: 0 0 340px;
  height: 260px;
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 12px rgba(0,245,255,0.5);
  position: relative;
}

.filmstrip-tile:hover { box-shadow: 0 0 22px rgba(0,245,255,0.8); }

.filmstrip-tile__overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 64px;
  background: rgba(10,10,10,0.85);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 16px;
}

.filmstrip-tile__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
}

.filmstrip-tile__count {
  background: var(--nitro-lime);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  padding: 4px 8px;
}

.filmstrip-row { padding-bottom: 16px; }

.filmstrip-captions {
  display: grid;
  grid-template-columns: 340px 340px 340px 340px;
  gap: 12px;
  padding: 12px 0 0 80px;
  position: relative;
  z-index: 1;
}

.filmstrip-captions p {
  font-family: var(--font-body);
  font-size: 13px;
  color: rgba(232,240,242,0.7);
  line-height: 1.5;
}

.hotspot-diagram {
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 16px;
  max-width: 320px;
}

.hotspot-diagram__caption {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
  margin-top: 12px;
}

/* Interior section (tabs) */
.interior-section {
  background: var(--screen-fog);
  padding: 56px 32px;
}

.interior-section__head { max-width: 1280px; margin: 0 auto 32px; }
.interior-section__head h2 { color: var(--revv-cyan); margin: 12px 0; max-width: 680px; }

.interior-tabs {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 240px 1fr;
  border: 2px solid var(--gridline-gray);
}

.tab-list {
  list-style: none;
  border-right: 1px solid var(--gridline-gray);
}

.tab-button {
  display: block;
  width: 100%;
  text-align: left;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: transparent;
  border: none;
  border-bottom: 1px solid var(--gridline-gray);
  border-left: 2px solid var(--gridline-gray);
  color: rgba(232,240,242,0.5);
  padding: 18px 16px;
  height: 56px;
  cursor: pointer;
}

.tab-button.is-active {
  border-left: 4px solid var(--turbo-purple);
  background: rgba(204,0,255,0.08);
  color: var(--turbo-purple);
}

.tab-content { padding: 28px; display: none; }
.tab-content.is-active { display: block; }

.tab-content__title {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--revv-cyan);
  margin-bottom: 6px;
}

.tab-content__count {
  display: inline-block;
  background: var(--nitro-lime);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  padding: 3px 8px;
  margin-left: 10px;
}

.tab-content__desc {
  font-family: var(--font-body);
  font-size: 14px;
  color: rgba(232,240,242,0.85);
  max-width: 600px;
  margin: 0 0 20px;
}

.tab-photo-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.photo-tile {
  background: var(--screen-fog);
  border: 3px solid var(--revv-cyan);
  box-shadow: 0 0 8px rgba(0,245,255,0.4);
  position: relative;
  height: 165px;
}

.photo-tile__overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(10,10,10,0.8);
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 12px;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--crt-white);
}

.photo-tile__overlay span.view { color: var(--revv-cyan); }

/* Mechanical section */
.mech-section { background: var(--lot-black); padding: 56px 32px; }
.mech-section__inner { max-width: 1280px; margin: 0 auto; }
.mech-section__head h2 { color: var(--crt-white); margin: 12px 0 12px; max-width: 640px; }

.mech-row {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 24px;
  margin-top: 32px;
}

.mech-cat-list { display: flex; flex-direction: column; gap: 16px; }

.mech-cat {
  background: var(--screen-fog);
  border: 2px solid var(--gridline-gray);
  padding: 16px;
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.mech-cat__icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  color: var(--revv-cyan);
}

.mech-cat__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--revv-cyan);
}

.mech-cat__count {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--nitro-lime);
  margin-top: 4px;
}

.mech-cat__desc {
  font-family: var(--font-body);
  font-size: 12px;
  color: rgba(232,240,242,0.8);
  margin-top: 4px;
  line-height: 1.5;
}

.mech-photos {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  align-content: start;
}

/* Gallery CTA close */
.gallery-cta {
  background: var(--turbo-purple);
  text-align: center;
  padding: 80px 32px;
  position: relative;
}

.gallery-cta__inner { max-width: 780px; margin: 0 auto; }

.gallery-cta h2 {
  font-size: 32px;
  line-height: 1.4;
  margin-bottom: 12px;
}

.gallery-cta h2 .data { color: var(--nitro-lime); }
.gallery-cta h2 .strike { color: var(--crt-white); position: relative; }

.gallery-cta h2 .strike::after {
  content: "";
  position: absolute;
  left: -2%;
  top: 50%;
  width: 104%;
  height: 6px;
  background: var(--pixel-magenta);
  transform: translateY(-50%);
}

.gallery-cta h2 .closing { color: var(--crt-white); display: block; margin-top: 16px; }

.gallery-cta p {
  font-size: 16px;
  color: rgba(232,240,242,0.85);
  margin: 0 auto 32px;
  max-width: 560px;
}

.gallery-cta__btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

.gallery-cta__btns .btn--lime { box-shadow: 4px 4px 0 var(--lot-black); }

/* ============= RESERVE PAGE ============= */
.reserve-header {
  background: var(--lot-black);
  position: relative;
  padding: 64px 32px 48px;
  overflow: hidden;
  min-height: 480px;
}

.reserve-stamp {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-8deg);
  font-family: var(--font-heading);
  font-size: clamp(60px, 9vw, 120px);
  color: var(--turbo-purple);
  opacity: 0.18;
  white-space: nowrap;
  z-index: 0;
  pointer-events: none;
  letter-spacing: 0.05em;
}

.reserve-header__inner {
  max-width: 1280px;
  margin: 0 auto;
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 40px;
  align-items: start;
}

.reserve-header h1 { font-size: 32px; line-height: 1.5; margin: 12px 0 24px; }

.reserve-header__art {
  align-self: end;
  margin-bottom: -32px;
}

/* Story block */
.story-block {
  background: var(--lot-black);
  padding: 48px 32px;
}

.story-block__frame {
  max-width: 860px;
  margin: 0 auto;
  background: var(--screen-fog);
  border: 2px solid var(--revv-cyan);
}

.story-block__bar {
  background: var(--gridline-gray);
  height: 36px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
}

.story-block__dot { width: 10px; height: 10px; background: var(--pixel-magenta); border-radius: 50%; }
.story-block__dot:nth-child(2) { background: var(--nitro-lime); }
.story-block__dot:nth-child(3) { background: var(--revv-cyan); }

.story-block__body { padding: 28px 32px; }

.story-block__head { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.story-block h2 { font-size: 18px; color: var(--crt-white); line-height: 1.5; margin: 12px 0; }

.story-block__strip {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--nitro-lime);
}

.story-block__badge {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  background: var(--nitro-lime);
  color: var(--lot-black);
  padding: 4px 8px;
  border: 2px solid var(--lot-black);
}

.story-block__body p {
  font-size: 15px;
  color: rgba(232,240,242,0.85);
  margin: 16px 0 24px;
  max-width: 640px;
}

.line-table {
  border-top: 2px solid var(--revv-cyan);
  border-bottom: 2px solid var(--revv-cyan);
  margin-top: 8px;
}

.line-row {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  padding: 14px 0;
  border-bottom: 1px dashed var(--gridline-gray);
  align-items: center;
}

.line-row:last-child { border-bottom: none; }

.line-row__label {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 14px;
  color: var(--crt-white);
}

.line-row__val {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--crt-white);
  text-align: right;
}

.line-row__val--magenta { color: var(--pixel-magenta); font-weight: 700; }
.line-row__val--lime { color: var(--nitro-lime); font-weight: 700; }

/* Contact form */
.contact-section {
  background: var(--screen-fog);
  padding: 64px 32px;
}

.contact-section__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 40px;
  align-items: start;
}

.step-chip {
  display: inline-block;
  background: var(--revv-cyan);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  padding: 4px 8px;
  margin-bottom: 12px;
  border: 2px solid var(--revv-cyan);
}

.contact-section h2 { font-size: 18px; color: var(--crt-white); margin: 16px 0 16px; }

.form-grid { display: flex; flex-direction: column; gap: 20px; margin-top: 24px; }

.form-field label {
  display: block;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--crt-white);
  margin-bottom: 8px;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  background: var(--lot-black);
  border: 2px solid var(--gridline-gray);
  color: var(--crt-white);
  font-family: var(--font-body);
  font-size: 15px;
  padding: 12px 14px;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--revv-cyan);
  outline: none;
  box-shadow: 0 0 8px rgba(0,245,255,0.4);
}

.form-field input::placeholder { color: rgba(46,46,68,1); }

.form-field__hint {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--gridline-gray);
  margin-top: 6px;
}

.radio-row { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }

.radio-row label {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--crt-white);
  cursor: pointer;
  letter-spacing: 0;
  text-transform: none;
  font-weight: 400;
}

.radio-row input[type="radio"] {
  appearance: none;
  width: 14px;
  height: 14px;
  border: 2px solid var(--revv-cyan);
  background: var(--lot-black);
  flex-shrink: 0;
}

.radio-row input[type="radio"]:checked {
  background: var(--revv-cyan);
  box-shadow: inset 0 0 0 2px var(--lot-black);
}

.form-submit {
  margin-top: 24px;
  width: 100%;
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--revv-cyan);
  color: var(--lot-black);
  border: 2px solid var(--revv-cyan);
  padding: 16px;
  cursor: pointer;
}

.form-submit:hover { background: var(--nitro-lime); border-color: var(--nitro-lime); }

.trust-sidebar {
  background: var(--screen-fog);
  border: 2px solid var(--turbo-purple);
  padding: 24px;
}

.trust-sidebar__title {
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--turbo-purple);
  margin-bottom: 16px;
}

.trust-list { list-style: none; }
.trust-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--crt-white);
  margin-bottom: 12px;
  line-height: 1.5;
}

.trust-list li::before {
  content: "▣";
  color: var(--nitro-lime);
  font-weight: 700;
  flex-shrink: 0;
}

.secure-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--pixel-magenta);
  color: var(--crt-white);
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.10em;
  padding: 6px 10px;
  margin-top: 12px;
}

/* Guarantee grid */
.guarantee-section {
  background: var(--turbo-purple);
  padding: 72px 32px;
  text-align: center;
}

.guarantee-section h2 {
  color: var(--lot-black);
  font-size: 26px;
  margin-bottom: 24px;
}

.guarantee-section .eyebrow { justify-content: center; color: var(--lot-black); }
.guarantee-section .eyebrow::before { background: var(--lot-black); }

.guarantee-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 32px;
  max-width: 1000px;
  margin-left: auto;
  margin-right: auto;
}

.guarantee-card {
  background: var(--screen-fog);
  border: 2px solid var(--lot-black);
  padding: 24px;
  text-align: center;
}

.guarantee-card__icon {
  width: 40px;
  height: 40px;
  margin: 0 auto 12px;
  color: var(--revv-cyan);
}

.guarantee-card:nth-child(2n) .guarantee-card__icon { color: var(--nitro-lime); }

.guarantee-card h3 {
  font-size: 12px;
  color: var(--crt-white);
  margin-bottom: 10px;
  line-height: 1.5;
}

.guarantee-card p {
  font-size: 13px;
  color: rgba(232,240,242,0.8);
  line-height: 1.6;
}

/* FAQ */
.faq-section {
  background: var(--lot-black);
  padding: 80px 32px 0;
}

.faq-section__inner {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}

.faq-section__inner .eyebrow { justify-content: center; }

.faq-section h2 {
  color: var(--crt-white);
  font-size: 18px;
  margin-bottom: 32px;
  line-height: 1.6;
}

.faq-section h2 .price { color: var(--revv-cyan); }

.faq-list {
  border-top: 1px solid var(--gridline-gray);
  text-align: left;
}

.faq-row {
  border-bottom: 1px solid var(--gridline-gray);
}

.faq-row__btn {
  display: flex;
  width: 100%;
  background: transparent;
  border: none;
  padding: 18px 16px;
  cursor: pointer;
  align-items: center;
  justify-content: space-between;
  text-align: left;
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 16px;
  color: var(--crt-white);
}

.faq-row__btn .toggle {
  font-family: var(--font-heading);
  color: var(--revv-cyan);
  font-size: 14px;
}

.faq-row__answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height .3s ease, padding .3s ease;
  font-family: var(--font-body);
  font-size: 15px;
  color: rgba(232,240,242,0.85);
  line-height: 1.75;
}

.faq-row.is-open {
  background: var(--screen-fog);
  border-left: 4px solid var(--revv-cyan);
}

.faq-row.is-open .faq-row__answer {
  max-height: 320px;
  padding: 0 16px 18px;
}

.faq-row.is-open .toggle { color: var(--nitro-lime); }

/* Final CTA strip */
.final-cta-strip {
  background: var(--revv-cyan);
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 0;
}

.final-cta-strip__btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--lot-black);
  color: var(--lot-black);
  font-family: var(--font-accent);
  font-weight: 900;
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 16px 32px;
  border: 2px solid var(--lot-black);
  width: 280px;
  height: 52px;
  justify-content: center;
}

.final-cta-strip__btn { color: var(--crt-white); }
.final-cta-strip__btn:hover { background: var(--nitro-lime); color: var(--lot-black); text-decoration: none; }

.final-cta-strip__btn svg { width: 14px; height: 14px; flex-shrink: 0; }

/* ============= UTILITIES ============= */
.section-cap-purple {
  height: 8px;
  background: var(--turbo-purple);
}

.cap--lime-checker {
  height: 16px;
  background:
    repeating-conic-gradient(var(--nitro-lime) 0 25%, var(--lot-black) 0 50%) 0 0 / 16px 16px;
}

/* ============= RESPONSIVE ============= */
@media (max-width: 1100px) {
  .hero__inner { grid-template-columns: 1fr; }
  .hero__title { font-size: 44px; }
  .feature-grid-layout { grid-template-columns: 1fr; }
  .feature-grid-text { border-right: none; padding-right: 0; }
  .item-grid { grid-template-columns: repeat(2, 1fr); }
  .stat-row { grid-template-columns: repeat(2, 1fr); }
  .testimonial-grid { grid-template-columns: 1fr 1fr; }
  .testimonial-card:nth-child(3) { transform: translateY(0); grid-column: span 2; }
  .filter-grid { grid-template-columns: repeat(2, 1fr); }
  .specs-grid { grid-template-columns: repeat(2, 1fr); }
  .inspection-grid { grid-template-columns: repeat(2, 1fr); }
  .guarantee-grid { grid-template-columns: repeat(2, 1fr); }
  .specs-header__inner { grid-template-columns: 1fr; }
  .reserve-header__inner { grid-template-columns: 1fr; }
  .gallery-header__inner { grid-template-columns: 1fr; }
  .contact-section__inner { grid-template-columns: 1fr; }
  .timeline-row { grid-template-columns: repeat(2, 1fr); }
  .timeline-row::before { display: none; }
  .mech-row { grid-template-columns: 1fr; }
  .mech-photos { grid-template-columns: repeat(3, 1fr); }
  .interior-tabs { grid-template-columns: 1fr; }
  .tab-list { display: flex; flex-wrap: wrap; border-right: none; }
  .tab-button { flex: 1; min-width: 50%; }
  .comparison-row { grid-template-columns: 1fr; }
  .comparison-panel + .comparison-panel { border-left: none; border-top: 4px solid var(--turbo-purple); }
  .gallery-section__head { grid-template-columns: 1fr; }
}

@media (max-width: 700px) {
  .nav__links { display: none; }
  .section { padding: 48px 20px; }
  h1 { font-size: 24px; }
  h2 { font-size: 18px; }
  .hero { padding: 48px 20px; }
  .hero__title { font-size: 28px; }
  .hero__title-line-1 { margin-right: -40px; }
  .item-grid-headline { font-size: 32px; }
  .stat-row { grid-template-columns: 1fr 1fr; }
  .feature-grid { grid-template-columns: 1fr; }
  .item-grid { grid-template-columns: 1fr; }
  .specs-grid { grid-template-columns: 1fr; }
  .inspection-grid { grid-template-columns: 1fr 1fr; }
  .guarantee-grid { grid-template-columns: 1fr 1fr; }
  .testimonial-grid { grid-template-columns: 1fr; }
  .testimonial-card:nth-child(2),
  .testimonial-card:nth-child(3) { transform: translateY(0); grid-column: 1; }
  .filter-grid { grid-template-columns: 1fr; }
  .timeline-row { grid-template-columns: 1fr; }
  .footer__inner { grid-template-columns: 1fr 1fr; }
  .footer__brand { grid-column: span 2; }
  .filmstrip-captions { grid-template-columns: 1fr; padding-left: 20px; }
  .filmstrip { padding-left: 20px; }
  .mech-photos { grid-template-columns: repeat(2, 1fr); }
}

